use semio_framework_test_fixtures::fixture_text;
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
#[derive(semio_framework_value::RetireOwned,Clone,Debug,PartialEq)]struct Row{title:Option<String>,count:i64,body:Vec<u8>}
#[derive(semio_framework_value::RetireOwned,Default,Clone,Debug,PartialEq)]struct Patch{title:Option<Option<String>>,count:Option<i64>,body:Option<Vec<u8>>}
impl RetainedRecordChange<Row> for Patch{
 const FIELD_COUNT:usize=3;
 fn empty_result()->Self{Self::default()}
 fn field_bytes(index:usize)->Result<usize,ValueError>{Ok(match index{0=>size_of::<RetainedRecordFieldChange<Row,Self,Option<String>>>(),1=>size_of::<RetainedRecordFieldChange<Row,Self,i64>>(),2=>size_of::<RetainedRecordFieldChange<Row,Self,Vec<u8>>>(),_=>return Err(invalid("test record field out of range"))})}
 fn field(index:usize)->Result<Box<dyn RetainedRecordChangeField<Row,Self>>,ValueError>{match index{0=>boxed_record_field(RetainedRecordFieldChange::new(|r:RetainedCloneRef<'_,Row>|r.project(0,|r|&r.title),|p:&mut Self,v|p.title=v)),1=>boxed_record_field(RetainedRecordFieldChange::new(|r:RetainedCloneRef<'_,Row>|r.project(1,|r|&r.count),|p:&mut Self,v|p.count=v)),2=>boxed_record_field(RetainedRecordFieldChange::new(|r:RetainedCloneRef<'_,Row>|r.project(2,|r|&r.body),|p:&mut Self,v|p.body=v)),_=>Err(invalid("test record field out of range"))}}
}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"original record action must fit authored4KiB quantum: {}",d.copy_bytes);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).map_err(|(e,..)|e).unwrap().0}
fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let g=grant(s.next_close_demands(4096).unwrap());assert!(s.close_step(g).unwrap().progress().fits(g));}}
fn drain<T:RetireOwned>(v:T){let mut c=ControlledRetirement::new(v).map_err(|(e,_)|e).unwrap();while !c.terminal_is_empty(){let g=grant(c.next_demand(4096).unwrap());assert!(c.step(g).unwrap().progress().fits(g));}}
fn row(v:&serde_json::Value)->Row{Row{title:v["title"].as_str().map(str::to_owned),count:v["count"].as_i64().unwrap(),body:v["body"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect()}}
fn patch(v:&serde_json::Value)->Patch{Patch{title:v.get("title").map(|v|v.as_str().map(str::to_owned)),count:v.get("count").map(|v|v.as_i64().unwrap()),body:v.get("body").map(|v|v.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect())}}
fn exercise(v:&serde_json::Value,cut:Option<usize>){observe(||());let mut a=source(row(&v["authored"]));let mut o=source(row(&v["original"]));let mut foreign=source(row(&v["authored"]));let pointers=(a.borrow().get().title.as_ref().map(|text|text.as_ptr()),a.borrow().get().body.as_ptr(),o.borrow().get().title.as_ref().map(|text|text.as_ptr()),o.borrow().get().body.as_ptr());let(mut c,heap)=observe(RetainedRecordChangeOwner::<Row,Patch>::new);assert_eq!(heap,(0,0));let mut turns=0;while !c.ready()&&cut.is_none_or(|cut|turns<cut){let d=c.demand(a.borrow(),o.borrow(),4096).unwrap();let g=grant(d);let(step,heap)=observe(||c.advance(a.borrow(),o.borrow(),RetainedCloneGrant{maximum_items:0,..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));let(step,heap)=observe(||c.advance(a.borrow(),o.borrow(),g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap.0,p.retained_capacity_bytes,"original record allocation receipt");assert_eq!(heap.1,p.released_bytes,"original record release receipt");turns+=1;assert!(turns<10000);}if turns>0{assert!(c.demand(foreign.borrow(),o.borrow(),4096).is_err());}if cut.is_none(){let g=grant(c.take_demand().unwrap());let(out,p)=c.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(out,patch(&v["patch"]));let mut result=row(&v["original"]);if let Some(title)=out.title.as_ref(){result.title=title.clone();}if let Some(count)=out.count{result.count=count;}if let Some(body)=out.body.as_ref(){result.body=body.clone();}assert_eq!(result,row(&v["authored"]));drain(result);drain(out);}c.begin_close();while !c.terminal_is_empty(){let g=grant(c.close_demand(4096).unwrap());assert_eq!(c.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());let(step,heap)=observe(||c.close_step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap.0,p.retained_capacity_bytes);assert_eq!(heap.1,p.released_bytes);}assert_eq!(observe(||drop(c)).1,(0,0));assert_eq!((a.borrow().get().title.as_ref().map(|text|text.as_ptr()),a.borrow().get().body.as_ptr(),o.borrow().get().title.as_ref().map(|text|text.as_ptr()),o.borrow().get().body.as_ptr()),pointers);close_source(&mut a);close_source(&mut o);close_source(&mut foreign);}
#[test]fn record_changes_original_sparse_fields_and_paid_frontier_match_neutral_cases(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🪡️field/🟰️change/🎚️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){exercise(row,None);eprintln!("[DEBUG] Record original {:?} sparse outputs and exact physical frontier receipts",row["id"]);}}
#[test]fn record_changes_partial_original_output_and_child_frontier_close(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🪡️field/🟰️change/🎚️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){for cut in f["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;exercise(row,Some(cut));eprintln!("[DEBUG] Record original {:?} partial original output/child frontier cut={cut}",row["id"]);}}}
